const rl = require("readline").createInterface({ input: process.stdin });
var iter = rl[Symbol.asyncIterator]();
const readline = async () => (await iter.next()).value;

void (async function () {
  const relations = (await readline()).split(" ").map((s) => s.split("->"));

  const inDegree = {};
  const next = {};

  // a依赖b, 即b执行完，才能执行a
  for (let [a, b] of relations) {
    // b的入度不变
    inDegree[b] = inDegree[b] ?? 0;
    // a的入度+1
    inDegree[a] = (inDegree[a] ?? 0) + 1;

    // b的后继节点集合添加a
    if (next[b] == undefined) next[b] = [];
    next[b].push(a);

    // a的后继节点集合不变
    if (next[a] == undefined) next[a] = [];
  }

  // queue收集第一层入度为0的点
  let queue = [];
  for (let task in inDegree) {
    if (inDegree[task] == 0) {
      queue.push(task);
    }
  }

  // 记录任务执行的顺序
  const ans = [];

  while (queue.length > 0) {
    // 如果同时有多个任务要执行，则根据任务名称字母顺序排序
    queue.sort();

    // newQueue用于记录下一层入度为0的点
    const newQueue = [];
    for (let fa of queue) {
      // fa执行，则加入已完成的任务列表
      ans.push(fa);

      for (let ch of next[fa]) {
        // fa是父任务，ch是子任务, 即fa执行完，才能执行ch
        // fa执行完，则对应ch的入度-1
        inDegree[ch] -= 1;

        // 如果ch的入度变为0，则加入新一层入度0的点集
        if (inDegree[ch] == 0) {
          newQueue.push(ch);
        }
      }
    }

    queue = newQueue;
  }

  console.log(ans.join(" "));
})();

