#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_TASK_SIZE 50000
#define MAX_TASK_NAME_LEN 10

typedef struct ListNode {
    int ele;
    struct ListNode *prev;
    struct ListNode *next;
} ListNode;

typedef struct LinkedList {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));
    link->size = 0;
    link->head = NULL;
    link->tail = NULL;
    return link;
}

void addLast_LinkedList(LinkedList *link, int ele) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));
    node->ele = ele;
    node->prev = NULL;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        node->prev = link->tail;
        link->tail = node;
    }

    link->size++;
}

// 缓存输入
char s[MAX_TASK_SIZE * MAX_TASK_NAME_LEN];

// 任务名数组，task[i]记录的是任务名，方便后续将任务名映射为索引i
char tasks[MAX_TASK_SIZE][MAX_TASK_NAME_LEN];
int tasks_size = 0;

// 记录每个任务的入度，inDegree[i] 表示任务i的入度
int inDegree[MAX_TASK_SIZE] = {0};
// 记录每个任务的子任务，next[i] 表示任务i的子任务集合
LinkedList *next[MAX_TASK_SIZE];

int cmp(const void *a, const void *b) {
    int a_index = *((int *) a);
    int b_index = *((int *) b);
    return strcmp(tasks[a_index], tasks[b_index]);
}

int main() {
    gets(s);

    char *token = strtok(s, " ");
    while (token != NULL) {
        char *tmp = strstr(token, "->");
        tmp[0] = '\0';
        tmp[1] = '\0';

        // a依赖b, 即b执行完，才能执行a
        // a任务
        char *a = token;
        // b任务
        char *b = tmp + 2;

        // a任务的索引号
        int a_index = -1;
        // b任务的索引号
        int b_index = -1;

        for (int i = 0; i < tasks_size; i++) {
            if (strcmp(tasks[i], a) == 0) {
                a_index = i;
            }

            if (strcmp(tasks[i], b) == 0) {
                b_index = i;
            }
        }

        if (a_index == -1) {
            a_index = tasks_size;
            strcpy(tasks[tasks_size++], a);
        }

        if (b_index == -1) {
            b_index = tasks_size;
            strcpy(tasks[tasks_size++], b);
        }

        // b的入度不变
        // a的入度+1
        inDegree[a_index]++;

        // b的后继节点集合添加a
        if (next[b_index] == NULL) {
            next[b_index] = new_LinkedList();
        }
        addLast_LinkedList(next[b_index], a_index);

        token = strtok(NULL, " ");
    }

    // queue收集第一层入度为0的点
    int* queue = (int*) malloc(sizeof(int) * tasks_size);
    int queue_size = 0;

    for (int i = 0; i < tasks_size; i++) {
        if (inDegree[i] == 0) {
            queue[queue_size++] = i;
        }
    }

    while (queue_size > 0) {
        // 如果同时有多个任务要执行，则根据任务名称字母顺序排序
        qsort(queue, queue_size, sizeof(queue[0]), cmp);

        // newQueue用于记录下一层入度为0的点
        int* newQueue = (int*) malloc(sizeof(int) * tasks_size);
        int newQueue_size = 0;

        for (int i = 0; i < queue_size; i++) {
            int fa = queue[i];

            // fa执行完成，则打印
            printf("%s ", tasks[fa]);

            if(next[fa] != NULL) {
                ListNode* cur = next[fa]->head;
                while (cur != NULL) {
                    // fa是父任务，ch是子任务, 即fa执行完，才能执行ch
                    // fa执行完，则对应ch的入度-1
                    int ch = cur->ele;

                    inDegree[ch] -= 1;

                    // 如果ch的入度变为0，则加入新一层入度0的点集
                    if(inDegree[ch] == 0) {
                        newQueue[newQueue_size++] = ch;
                    }

                    cur = cur->next;
                }
            }
        }

        queue = newQueue;
        queue_size = newQueue_size;
    }

    return 0;
}
